def rencana(optimal, train, dev, biaya):
    bias = round(train - optimal, 6)
    var = round(dev - train, 6)
    skor_b = bias / biaya["bias"]
    skor_v = var / biaya["variance"]
    return "bias" if skor_b >= skor_v else "variance"

