import numpy as np

dev = [0.40, 0.31, 0.25, 0.22, 0.21, 0.22, 0.24, 0.27]

def epoch_terbaik(errs, patience=2):
    terbaik, idx, sabar = float("inf"), 0, 0
    for i, e in enumerate(errs):
        if e < terbaik:
            terbaik, idx, sabar = e, i, 0
        else:
            sabar += 1
            if sabar >= patience:
                break
    return idx, terbaik

print(epoch_terbaik(dev))

